function formatINR(n, opts = {}) {
  if (n >= 10000000) return `₹ ${(n / 10000000).toFixed(opts.decimals ?? 2)} Cr`;
  if (n >= 100000) return `₹ ${(n / 100000).toFixed(opts.decimals ?? 1)} L`;
  return `₹ ${n.toLocaleString('en-IN')}`;
}
function formatINRFull(n) {
  return `₹ ${n.toLocaleString('en-IN')}`;
}
